import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    if n < 2:
        print(0)
        return

    dp = [[False] * n for _ in range(n)]
    count = 0

    for i in range(n):
        dp[i][i] = True

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 2:
                if s[i] == s[j]:
                    dp[i][j] = True
                    count += 1
            else:
                if s[i] == s[j] and dp[i + 1][j - 1]:
                    dp[i][j] = True
                    count += 0 if length < 2 else 1

    print(count)

if __name__ == "__main__":
    main()
